
import json
import os

# 处理t2052
with open("data/baihua-tasks/t2052.json", "r", encoding="utf-8") as f:
    data = json.load(f)
translations = data["translations"]

translations[0]["modern"] = "【法师家世】【义解】法师法名祎，字玄奘，俗家姓陈，是汉代太丘长陈仲弓的后裔，原本居住在颍川，后来迁居河南，子孙便成为缑氏县人。他的高祖陈湛，是北魏清河太守；曾祖陈山，任魏征东将军、南阳郡开国公；祖父陈康，先后任北齐国子博士、司业，又转任礼部侍郎；父亲陈惠，品行高洁有雅正的操守，早年就通晓经学，身高八尺，眉清目朗，身着宽袍博带，有儒者风度，当时人将他比作东汉名士郭有道。郡中举荐他为孝廉，授官陈留令，又迁任江陵令，后来隋朝国运将衰，他便断绝了出仕做官的念头，萌生了隐居山林的志向，有识之士都十分敬重他。母亲是广平宋氏、洛州长史宋钦的女儿，法师是家中第四子。法师从襁褓之时，就显露出温厚聪慧的品性；待到二十岁左右，更表现出贞正淳和的品格，机智超常，聪敏过人。因为宿世种下的善根，他早年就厌弃世俗樊笼，心思向往佛门，精神追慕觉悟大道。大业年间，朝廷下诏剃度僧尼，当时的使者是大理卿鄼善果。"

translations[1]["modern"] = "【初入释门】【义解】鄼善果有识人之名，一见到法师就对旁人说：“这个孩子年纪虽小，风骨却十分出众，假如出家为僧，必定会成为佛门栋梁。”于是准许他剃度，安置在东都净土道场。当时寺里有景法师讲《涅槃经》，法师手捧经卷诚心受教，甚至废寝忘食；又跟随严法师学习《摄大乘论》，喜爱学习的劲头更甚，这些经论都是听一遍就基本理解，再看一遍就没有遗漏的地方。众人都十分惊异，就让他升座复讲，他复述经文、阐释义理十分流畅完备，僧俗间的美好名声从这时开始传扬，当时他才十五岁。后来隋朝失去天下，天下大乱，法师禀告兄长：“这里虽然是父母之乡，但丧乱到这种地步，怎么能守在这里等死？现在听说唐主率领晋阳的部众，已经占据长安，天下人都归依他，如同投奔父母一般，我愿意和兄长前去投奔。”兄长听从了他的话，就和他一同前来，当时是武德元年。这时候国家基业刚刚草创，京城还没有讲经的法席。当初隋炀帝在东都建立四大道场，征召天下名僧居住，景、脱、基、暹四位法师是其中的翘楚。"

translations[2]["modern"] = "【入蜀求学】【义解】隋朝末年国家动乱，供给断绝，这些名僧大多游历到绵蜀之地，通晓佛法的僧众在那边又兴盛起来。法师禀告兄长：“这里没有法事可做，我愿意到蜀地求学。”兄长听从了他，经过子午谷进入汉川，遇到空、景两位法师，都是道场中的大德，便跟随他们学习，之后一同前往成都，即使在行路途中，也一直手捧经卷随时请教。等到了益州，《摄论》《毗昙》都已经听了一遍。当时各地高僧都聚集在这里，大开法筵，法师又听宝暹讲《摄论》、道基讲《毗昙》、志振讲《迦延》，珍惜每一寸光阴，四五年间，就通晓了各部经论。他讲法的座下，常有数百人听讲，他领悟经义的才华，众人都十分佩服。法师的兄长于是住在成都空慧寺，就是长捷法师，他风神俊朗，身材魁伟，相貌秀美，每次走到大街上，路人见了没有不停车驻足观看的。他讲《涅槃经》《摄大乘论》《阿毗昙》，兼通史传，又擅长老庄学说，被蜀地人所仰慕，总管酇公、行台尚书韦云起等人都对他十分敬重。"

translations[3]["modern"] = "【受具离蜀】【义解】至于文辞谈吐，风雅蕴藉，接引开导凡俗，写文章书信，随和谈笑，融洽道俗之情，这些方面长捷法师胜过弟弟；但要说亭亭独立、不染尘俗，遍历八方、穷究玄理，以降伏魔障为志向，以继承圣道为心愿，匡正衰颓的佛法纲纪，折服不同的学说，历经风波而心意不倦，面临大难而气节更高，通晓先贤的深疑，开启后学的未悟，为后世留下义理功德，为当下树立修行标准，这些方面玄奘法师是生来少有匹敌的，不只是长捷法师做不到。然而兄弟二人，德行清规，美名品质，即使是庐山的慧永、慧远两位大师，也不能和他们相比。法师二十一岁，在武德五年于成都受具足戒，坐夏学习律藏，五篇七聚的律宗教义，也一遍就通晓了。蜀地的经论，他已经研究穷尽了，更想要进入京城，请教不同的义旨，但受条规限制，又被兄长挽留，不能如愿，于是私下和入蜀的商人结伴，泛舟三峡，沿江而下，到了荆州。"

translations[4]["modern"] = "【遍参大德】【义解】法师住在天皇寺，当地的僧俗久仰他的名声，既然他来到这里，都请他讲法。法师为他们讲《摄论》《毗昙》，各讲了三遍。讲完之后又向北游历，寻访先前的高僧大德，到相州拜见休法师，请教疑难问题；又到赵州拜见深法师，学习《成实论》；又进入长安，跟随岳法师学习《俱舍论》，都是听一遍就穷尽其中的义旨，过目就记在心里。又向京城的各位大德寻访各家学说的异同，仆射宋公萧瑀兄弟对他十分敬重，奏请让他住在大庄严寺。法师已经遍访各位贤德高僧，全面领受了他们的学说，详细考察其中的义理，发现各家各有传承，和圣典对照，也有隐显不同的地方，没有统一的定论，于是发誓要游历西方，请教心中的疑惑，同时取来《十七地论》等经论，来解释众人的疑问，也就是现在的《瑜伽师地论》。他又说从前法显、智严也是一时的贤士，都能求法来利益众生，我应当继承他们的事业，于是结伴向朝廷上表请求西行，有诏令不允许，其他人都退下了，只有法师没有动摇。他正打算独自西行，又听说西路艰险难行。"

translations[5]["modern"] = "【西行先兆】【义解】于是自己试炼心性，用世俗的各种苦恼来调伏自心，确认自己能够胜任不退转，这才进入佛塔，启请禀告自己的心愿，祈求众圣冥冥中加被，让他往返没有危难。当初法师出生的时候，母亲梦见法师穿着白衣向西走，母亲问：“你是我的儿子，现在要去哪里？”他回答说：“为了求法而去。”这就是他西行去迦毗罗卫国的先兆。贞观三年，他即将启程，又求取祥瑞征兆，夜里梦见大海中有苏迷卢山，十分壮丽庄严，想要登山，却见洪涛汹涌，他并不畏惧，决意踏入海中，忽然看见莲花从波外涌出，踏着莲花前行，片刻就到了山下，山又陡峭无法攀登，他纵身腾起，有一阵旋风托着他上升，到了山顶，四面望去辽阔无际，没有任何阻碍，他欢喜地醒了过来，于是就出发了，当时他二十九岁。当时有秦川僧人孝达，在京城学习完毕要回乡，法师和他一同出发，辗转抵达瓜州，打听西路的路况，都说：“流沙没有路。"

translations[6]["modern"] = "【初涉沙碛】【义解】行路的人多结伴而行，以牛马粪和骸骨作为路标，风沙一起，骸骨也会被埋没，沿途多有鬼魅热风之类的异象，东西八百多里，想要独自行走的，始终无法通过。”法师听后忧愁烦闷，无计可施，于是礼佛发愿，希望能有一个人引路带他过关，也就是玉门关。玉门关倚靠着胡卢河，关西一百里有第一烽，烽下有水，一共有五烽，五烽之外就没有戍守巡逻的人了，都是大沙漠。他于是访得一个胡人，答应送他过关，到出发的时候胡人又反悔了，法师勉强说服他才上路。夜里到了河边，距离关口十多里，上游有胡桐树，胡人砍树造桥，铺上草填上沙，驱马过河。渡过河之后，法师心中十分欢喜，各自铺下被褥休息。半夜的时候，胡人起来，拔刀走向法师，想要加害他，法师立即起身念佛诵经，胡人又坐了回去，过了一会儿对法师说：“国家的法律，私自出境罪名极重，前面五烽的路，从烽下经过一定会被他们抓住。"

translations[7]["modern"] = "【渡关受助】【义解】终究不能幸免，只要在一处被擒就是死路，弟子也有家室拖累，怎么能承担罪责？王法是不能触犯的，和师父一起回去吧。”法师回答说：“我玄奘只可向西而死，绝不东归而生，檀越不能送的话尽管回去，我独自前去。”胡人说：“师父要是被抓住，还会牵连到我，终究免不了罪。”法师为他发重誓，说即使粉身碎骨，也绝不会牵连他，指着天地星月重又发誓，胡人才和法师辞别，法师送给他一匹马离去。于是法师连夜出发，到了第一烽，在水边饮马，不一会儿，飞箭频频射来，几乎射中膝盖，他知道被守军发现了，立即上前，烽上的人举着火把问：“是什么人？要去哪里？”法师摘下帽子露出僧服，回答说：“我从京师来，想要到婆罗门国求法。”守军带他上烽去见校尉王祥，校尉严厉责问他，法师详细陈述了西行的意愿，声泪俱下，王祥也怜悯落泪，说：“师父能这样做就尽管去吧，倘若如您所愿，也是国家的益处，师父先休息吧。”于是安置他住下，天亮为他准备食物。"

translations[8]["modern"] = "【沙碛迷途】【义解】又送给他干粮，亲自送了十多里说：“师父不要经过其他烽燧，第五烽外有野马泉，可以在那里取水再走。”法师过了第五烽，遇上大风沙，找不到泉眼，天暗了下来，在一条沙沟边停下，要下马饮水，装水的马袋很重不慎失手，倒了下来，只剩下够喝一口的水，剩下的都流光了，千里行路的资粮，一下子就耗尽了，烦恼难以言说。三更之后又继续前行，不认路，只朝着西北望星月前进，到第二天午后，已经十分干渴，虽然有干粮，却干得吃不下，这样四夜五天，没有一滴水沾喉，人马都困乏得不能再走，于是卧在沙中，默念观音菩萨，连说话的力气都没有，气息将近断绝。到第五夜，忽然有凉风吹来，十分凉爽，身体得以清醒，马也能站起来，又勉强走了二十多里，还是卧倒走不动，梦见一位大神，告诉他快走，为什么还卧着。于是又起身，马忽然改道而行，拉不回来，走了十多里。"

translations[9]["modern"] = "【高昌留僧】【义解】就遇到一池水，清凉澄澈，法师十分欢喜，饮了马，自己也洗漱饮水，又取干粮喂马，池边也有青草，到天亮马恢复了力气，人也恢复了精神，又用一天一夜在水边休整，第二天盛水继续前进，又走了三天，才到达伊吾。在沙漠北边之外，又遇到鬼魅，每天都有好几次，困顿艰难，脱险的事情难以一一记述。到了伊吾之后，遇上高昌国的使者，回去向国王说法师到来的消息，国王十分欢喜，派人牵骆驼来迎接，法师到了高昌，国王和他相见悲喜交加，想要留下法师，不让他西去，法师于是绝食四天，以诚心打动国王，国王心意回转，王母愿意和法师结为母子，国王愿意和法师结为兄弟，答应放他西去。法师答应了，国王欢喜地请他讲《仁王经》，并为他剃度四个沙弥，制作数十套法服，差派官员，准备马匹、脚力成倍送行，又写了二十四封书信，给突厥叶护可汗等各国国王，并附上绫罗绸缎五百多匹。"

translations[10]["modern"] = "【终抵印度】【义解】让人送信说：“这位法师是我的弟弟，希望可汗怜悯法师如同怜悯我，让他能到达婆罗门国。”于是法师辞别离去，到了叶护可汗的衙所，可汗十分欢喜，差人一路护送，最终抵达迦湿弥罗，也就是旧时说的罽宾国，这都是可汗的威望、高昌王的助力。中途经过葱山雪岭、热海铁门的危难之事，以及各国国王礼接迎送的仪轨，不能一一详述。迦湿弥罗国有一位大德，名叫僧称，精通经论，法师跟随他学习《俱舍论》《顺正理论》《因明》《声明》以及《大毗婆沙论》。国王怜悯他为求尽学而来，没有经本，于是派给他十名书手，让他们为法师抄写经本，其余所需，都敕令供给。学习完毕之后向东南出发，进入磔迦国，同行的有二十多人，一起渡旃陀罗婆伽河，向东走到波罗奢大林中，遇到盗贼，所带的衣物资财都被劫掠一空，仅保住性命到了村里，和众人乞讨，各得到衣服。接着到磔迦东境，有一大片庵罗林。"

translations[11]["modern"] = "【林中学法】【义解】林中有一位七百岁的婆罗门，看他的面貌像是三十多岁，通晓《中论》《百论》以及吠陀经典，说是龙猛菩萨的弟子，法师在这里停留一个月，学习《经百论》。又向东到那仆底国，跟随调伏法师学习《对法论》《显宗论》《理门论》等论典。又向东到阇烂达罗国那伽罗寺，跟随月曹法师学习《众事分毗婆沙》。又向东到禄勒那国，跟随阇那鞠多大德学习经部《毗婆沙》，又跟随蜜多犀那论师学习《萨婆多辩真论》。辗转到达劫毗陀国，礼拜圣迹——佛陀从前在忉利天为报母恩，安居三月说法完毕，乘三道宝阶下到人间的地方。又向西北到羯若鞠阇国（汉译曲女城），跟随毗邪犀那三藏学习《佛使毗婆沙》《日胄毗婆沙》。从这里向东南，到阿逾陀国，礼拜圣迹之后，顺殑伽河东下，八十多人同船，要去阿耶穆佉国，河的两岸都是阿逾迦林。"

translations[12]["modern"] = "【河上遇盗】【义解】林木茂密深广，忽然从林中冲出十多艘贼船，划桨迎面而来，船上的人惊慌骚乱，好几个人投了河。盗贼把船逼到岸边，让众人脱下衣服，搜求珍宝。这些盗贼一向信奉突伽天神，每年秋天都要找一个形貌端正美好的人，杀了取肉血用来祭祀天神求福。他们见法师仪容俊美，互相看着十分欢喜，于是盗贼派人取水，在花林中和泥涂地作祭坛，把法师拉上祭坛坐下，让几个人拔刀站在旁边，就要挥刀杀他。法师告诉他们说：“我远来求法，想要传扬还没听说过的佛法，这个心愿还没实现，檀越杀了我，恐怕没有福报。”盗贼不听，法师知道难免一死，对盗贼说：“希望赐给我一点时间，不要逼恼我，让我安心正念，这也是檀越的恩泽。”于是法师专心观想睹史多天慈氏菩萨所在之处，心中仿佛登上苏迷卢山，越过一二三天，见到睹史多宫，慈氏菩萨在妙宝台上，菩萨眷属围绕，这时身心欢喜，忘了自己在祭坛上，忘了有盗贼在旁边。"

translations[13]["modern"] = "【化盗归依】【义解】同行的人都放声号哭。片刻之间，黑风四起，折断树木、飞沙走石，河里涌起大浪，船只都被冲翻。盗贼们大惊，问同行的人说：“这个沙门从哪里来？叫什么名字？”同伴回答说：“从支那国来求法的就是他，各位要是杀了他，会有无量罪过，而且看这风浪的样子，天神已经发怒了，应当赶快忏悔。”盗贼害怕了，相继忏悔谢罪，稽首归依。法师这时正念入定没有察觉，盗贼用手碰他，他才睁开眼，对盗贼说：“到时候了吗？”盗贼说：“不敢害师父，愿接受忏悔。”法师接受了他们的礼谢，广为他们说法，让他们发心向善，盗贼们互相劝告，把所有的贼具都扔进河里，抢来的衣物都还给本主，并且都受了五戒。风浪立刻平息，盗贼们欢喜顶礼辞别。同行的人都惊叹敬佩，远近听说这件事的人没有不称奇的。法师经过几个国家，又向东北到室罗伐悉底国，也就是旧时的舍卫国，名字有讹误，那里圣迹很多，法师都一一礼敬。"

translations[14]["modern"] = "【礼遍圣迹】【义解】又到吠舍离城，观礼维摩诘居士的旧宅，以及佛陀同意魔王入涅槃的地方，都前往礼敬。从这里又到摩揭陀国，那里圣迹极多，法师停留了七天，才礼拜完毕。从这里向东南走四百多里，到菩提树，那里周围三十里内，圣迹尤其多，法师停留了八九日，才礼拜完毕。到第十天，那烂陀寺派了四十位大德，来迎接法师到寺庄，住在大目揵连的本村。第二天吃完饭后，又有二百多僧人以及一千多施主，举着幢盖、花香来迎接，引法师进入那烂陀寺。到了之后，全寺僧众都集合起来，法师和他们相见，众人坐下，让维那宣布法师住寺，寺内所有一切供给都和常住僧相同。众人相见完毕，派了二十位有德行的僧人，带法师参谒正法藏，也就是戒贤法师。这位法师博闻强识，佛法以及外道的经书全都通达，又是寺中最年长的，当时已经一百六十岁，众人共同尊敬他，不敢直呼他的名字。"

translations[15]["modern"] = "【谒戒贤师】【义解】所以称他为正法藏。法师跟随众人进去拜见，依师徒之礼，竭尽恭敬，顶礼赞叹完毕，正法藏让法师和众僧坐下，问他从哪里来，法师回答说从支那国来，想要在师父处学习《瑜伽师地论》等经论。戒贤法师听后流下泪来，叫来弟子觉贤，让他讲述三年前患病的因缘。觉贤说：“和尚三年前患病，四肢拘急，如同火烧刀割一般痛苦，心里厌恶这个身体，想要绝食了结性命。夜里梦见金色天人对和尚说：‘你不要厌恶这个身体，身体是修行的法器，得到人身修行十分难得，你过去曾经做过国王，恼害过很多众生，所以招致这个苦报，应当忏悔自责，礼诵行道，广传正法，业障就可以消除，只是想绝食舍弃性命，终究不能了脱，死后受生还是要受苦，如同井轮回转不停。再过三年多，有支那国的僧人想来这里学习诸经论，已经出发在路上了，你要等他，为他演说传授。'”"

translations[16]["modern"] = "【梦授前记】【义解】“‘他得到佛法之后，会流通传播，凭借这个功德，你的罪业自然消灭。我是曼殊室利菩萨，怜悯你，特意来告诉你，你应当依我的话去做，从今天起，你的病痛会渐渐消除。’说完就不见了。从那以后，和尚的病渐渐痊愈。”正法藏又问法师：“你在路上走了多久？”法师回答说：“走了三年，快到四年了。”既然和从前的梦境情形相同，正法藏对法师十分安慰嘉许。法师亲耳听到这个授记，悲喜交加，再次起身礼谢，说完之后，告辞出来，被安置在幼日王院，供养了七天之后，又安排他住在上房第四重阁楼，增加供给，每天给步罗叶一百二十枚、槟榔子二十颗、豆蔻二十颗、龙脑香一两、供大人米一升，酥油、乳酪、石蜜等，每天都充足有余，这些供养一次的份额，好几个人都吃不完。还配给净人、婆罗门各一名，出门乘象，有二十人随从，免除一切僧事。寺内主客僧众上万人，能得到这种供给的。"

translations[17]["modern"] = "【那烂陀受供】【义解】连法师在内一共只有十人。所谓供大人米，就是粳米，颗粒大如乌豆，做成饭之后，香气能飘一百多步，只有摩揭陀国有这种米，其他国家没有，种植得也少，只有国王以及广知佛法的大德才能吃到，其他人得不到，所以叫供大人米。法师在外国游历所受到的敬重，所到之处都是这样。法师安置妥当之后，前往王舍城观礼圣迹，几天才礼拜完毕，回到那烂陀寺，请戒贤法师讲《瑜伽师地论》，一起听讲的有数千人。这样听《瑜伽师地论》三遍，《顺正理论》一遍，《显扬论》《对法论》《因明》《声明》《集量论》等各一遍，《中论》《百论》各三遍，至于《俱舍论》《毗婆沙》《六足阿毗昙》等，已经在迦湿弥罗等国听过，在这里只是研读解决疑难而已。这样五年，昼夜不懈，听完之后，又前往伊烂拏钵伐多国，寻访礼敬圣迹。那里有一座孤山，十分秀丽，山中有精舍，精舍中有栴檀木的观自在菩萨像，特别灵验，有什么愿求。"

translations[18]["modern"] = "【观音祈愿】【义解】诚心祈祷都能实现。守护佛像的人怕香烛烟尘污损佛像，在外面十步远的地方做了栏杆，人们散花请愿都在栏杆外，不许进入里面。法师想要前去祈请，买了各种各样的花，穿成花鬘，到了像前，至诚礼拜完毕，向菩萨跪下发了三个愿：第一，在这里学习完毕之后，能够平安回到本国的话，愿花停在菩萨手上；第二，所修的福慧，愿往生睹史多天宫侍奉慈氏菩萨，如果能如愿，愿花挂在菩萨两臂上；第三，圣教说众生界中有一部分众生没有佛性，我现在自己有疑惑，不知道有没有，如果有佛性、修行可以成佛的话，愿花串在菩萨头顶上。祈祷完毕，将花鬘远远抛散，全都如他所愿落在对应的地方，满足了所求，法师欢喜无量，在旁边看到的人没有不礼敬而结下法缘的。从这里又巡游各国，直到南海之滨，观礼圣迹，寻访师友，又回到钵伐多国，有几位大德学识值得师从，于是停留两年，学习正量部的根本《阿毗达摩》以及《摄正法论》《教实论》等。"

translations[19]["modern"] = "【杖林论学】【义解】又回到那烂陀寺，参礼正法藏之后，又前往杖林山胜军论师的住处。胜军论师是刹帝利种姓，自幼喜好内外经书，五明数术没有不穷尽览阅的，常住在杖林山，收徒教授，经常讲说佛经，道俗前来归依的每天有数百人，各国国王也多次前来探望礼拜，为他洗足供养，封赏城邑，当时人称他为“步擭”，也就是食邑的意思。法师跟随他学习《唯识抉择论》《意义理论》《成无畏论》《不住涅槃论》《十二因缘论》《庄严经论》，以及听讲《瑜伽论》《因明》等完毕。有一天夜里，法师忽然梦见那烂陀寺房院荒芜污秽，里面拴着水牛，没有僧人，他从幼日王院西门进去，看见第四重阁上有一个金人，相貌端严，光明满空，远远指着寺外对法师说：“你随我看。”法师顺着手指向外望，看见村邑、林池都被火烧成灰烬。金人说：“你应该早点回去。”"

translations[20]["modern"] = "【梦示归期】【义解】“这里十多年之后，戒日王驾崩，印度荒乱，恶人相害，就会变成这个样子，你要知道。”说完就不见了。法师醒了之后惊叹，告诉胜军论师，胜军回答说：“三界没有安宁，本来就是这样，这是圣人的垂诫，不能不依从。法师西行以来，一直有菩萨护念，要回东土的时候，会示现无常来劝你归去，如果不是契合圣心，谁能有这样的预兆呢？”永徽末年，戒日王果然驾崩，印度饥荒战乱，都和梦中说的一样，朝廷使者王玄策亲眼见到了这件事。法师在那烂陀寺的时候，看到大德师子光等人建立《中论》《百论》的宗旨，破斥《瑜伽论》等义理，法师对他们说：“圣人作论，终究不会互相违背，只是学的人没有贯通而已。”于是撰写了《会宗论》三千颂，戒贤法师以下的人看了都称赞好，这部论在当地广为流传。先前有南印度王的灌顶师名叫般若鞠多，通晓正量部义理，撰写了《破大乘论》七百颂。"

translations[21]["modern"] = "【曲女赴会】【义解】当时戒日王征讨贼寇行军到乌荼国，小乘师等人珍重这部论，拿给国王看，并且请求和大乘师辩论，国王答应了，于是写信给那烂陀寺，差派四位通晓大小乘宗旨以及外道经书的大德，到行宫来，准备和小乘、外道辩论义理。正法藏于是选派海惠、智觉、师子光以及法师四人应国王之命。还没出发，就有顺世外道前来求辩论，写了四十条义理悬挂在寺门上，法师派人取下立论，叫来外道一起辩论，往复三四番，婆罗门就无话可说了。先前有约定，辩论输的人要斩首相谢，外道请求依照先前的约定，法师说：“我是佛门沙门，连昆虫都不伤害，何况杀人呢？”外道十分欢喜，请求终身做侍从，听到的人没有不称庆的。当时正要前往乌荼国，法师找来那部《破大乘论》披阅，好几处有疑问，对所降伏的婆罗门说：“你曾经听过这部论的义理吗？”婆罗门回答说曾经听过，当时就记得很熟，法师让他讲了一遍。"

translations[22]["modern"] = "【会拘摩罗】【义解】法师完全掌握了这部论的要旨，于是找出其中的错谬，用大乘义理破斥，写成一千六百颂，名叫《制恶见论》，呈给戒贤以及各位大德，大家都称赞说：“用这部论来穷究对方的漏洞，没有什么敌人不能攻破的。”法师通达了对方的宗旨，就放了所降伏的婆罗门，让他随意去哪里，外道欢喜辞别，去东印度向拘摩罗王称述法师的德行，国王听了十分喜悦，派使者来请法师，使者再三来请，法师才前去。当时法师正准备回国，已经收拾好行装，那烂陀的大德和徒众都劝他留下，法师想到这里的经论还有缺少，自己本来的心愿是取来流通，不能违背初心，坚决不答应，于是辞别，带着经像前往拘摩罗王的住处。那个国家先前没有流行佛法，多信外道婆罗门教，法师到了之后，异道之人聚集如云，请国王主持辩论来检验胜负，法师精妙的辩才一开，邪道之人就像草被风吹倒一样，国王更加崇敬，用谦卑的言辞请教诸佛的功德，希望开示缘由，法师为国王称述如来三身利益众生的道理。"

translations[23]["modern"] = "【见戒日王】【义解】因此为国王撰写《三身论》三百偈，国王欢喜得前所未有，顶戴受持。当时戒日王听说法师在拘摩罗王那里，吃惊地说：“我多次请他都不来，为什么在这里？”派使者告诉拘摩罗王，把支那法师送来。拘摩罗王知道戒日王钦慕法师，下令准备象车二万辆、船三万艘，法师溯殑伽河前往戒日王的住处。到了羯朱祇罗国，国王见了法师，顶礼双足，散无量花，赞叹完毕，说道：“弟子先前派人请法师，为什么不来？”法师回答说：“当时奉命的时候，听受经论还没结束，所以没能来参见大王。”国王问：“师父从支那国来，那个国家有《秦王破阵乐》的歌舞曲，秦王是什么人？有什么功德，值得这样歌咏赞美？”法师回答说：“秦王就是支那国现在的天子，本国看到国王有圣德，能除凶暴、润泽众生，就作歌来歌咏他。秦王是大圣人，为苍生拨乱反正，重安宇宙，再曜三光。"

translations[24]["modern"] = "【曲女论胜】【义解】“六合之内都感怀他的恩德，所以有这样的歌咏。”国王说：“这样的圣人，是上天派来做众生之主的啊。”于是请法师进入行宫，陈设各种供养。国王说：“听说您造了《制恶见论》，在哪里？”法师回答说：“在这里。”于是派人取来观看，国王十分喜悦，对他的门师等人说：“弟子听说，太阳出来之后，萤烛的光就被盖过了，师父们所推崇的宗旨，都被他破完了，试着救一救看。”小乘诸位僧人没有敢说话的。国王说：“师父的论太好了，这里的诸位法师都信服了，恐怕其他国家的小乘外道还守着愚迷，希望在中印度曲女城为师父开一场法会，召集五印度的沙门、婆罗门、外道等，显扬大乘，让他们改邪归正，不是一大盛事吗？”当天就发敕令，普告天下所有人集合到曲女城，观看支那法师论义。从冬初出发，直到腊月才到会场，四方来的沙门、婆罗门、外道等，博学多闻的人到了数千人。国王先下令建造大殿，能容纳一千多人，在殿中安置佛像，陈设香花音乐。"

translations[25]["modern"] = "【辞王归国】【义解】设食布施完毕，请法师升座，标举论宗，命众人来辩难，整整十八天，没有一个人敢上前问难。国王赞叹不已，赐给法师银钱三万、金钱一万、上等细布衣一百具，又让大臣拿着法师的袈裟，巡行遍告众人说：“支那法师论义得胜，十八天来，没有人敢问难，大家都应当知道。”众人十分欢喜，为法师各自立美名，大乘僧人称他为摩诃耶那提婆，汉译大乘天；小乘人称他为木叉提婆，汉译解脱天。大家烧香散花，礼敬而去，从此法师的德音远扬四方。法会结束后法师要回国，国王留他，再观赏为期七十五天的大布施，看完之后辞别回国。国王施舍大象一头，金银钱数万，法师接受了大象，没有接受钱等物。戒日王、拘摩罗王等十八大国王流泪辞别，法师取北路归国，历经艰险，翻过雪山、葱岭等，经过三十多个国家，到达于阗，向朝廷上表奏请归国，敕令于阗王多供给驼马，送到敦煌，在贞观十九年春正月。"

translations[26]["modern"] = "【返京弘译】【义解】到达长安，从西域请得转法轮像等七躯、经论六百五十七部、佛肉舍利一百五十粒。二十五日将经像送到弘福寺之后，前往洛阳谒见太宗皇帝。三月一日，奉敕回到京师，就在弘福寺翻译，并且撰写《大唐西域记》。到贞观二十年秋七月十三日，进上新翻译的经论，并且请求皇帝御制经序，同时进献《西域记》，承蒙皇帝亲笔回信，极力褒扬赞美。敕书说：“法师您早有高洁的品行，早年超出尘俗，泛宝舟而登彼岸，探寻妙道而开辟法门，弘扬大法，荡涤众罪。所以慈云将要卷收的时候，您舒展它荫蔽四方；慧日将要昏暗的时候，您点亮它照彻八极。舒展点亮的，就是法师您啊。朕学识浅薄心思愚拙，对事物尚且迷惑，何况佛教幽微，怎么能揣测？请为经题序，不是朕能做到的。”又说：“新撰写的《西域记》，朕会亲自披览。”敕令称奘尚法师，法师又上表谢恩，再次请求作序，到贞观二十二年。"

translations[27]["modern"] = "【帝许制序】【义解】皇帝驾幸玉华宫，六月下诏追召法师，法师到了之后，以特殊的礼节接待。皇帝问：“师父近来又翻译了什么经论？”法师回答说：“近来翻译了《瑜伽师地论》一百卷。”皇帝说：“这部论很大，是什么圣人所作？又阐明什么义理？”法师回答说：“这部论是弥勒菩萨造的，阐明十七地的义理。”皇帝问什么是十七地，法师回答了名称并说明了大要，皇帝十分高兴，于是派使者去京城取论，论取到之后，皇帝亲自披阅更加欢喜，于是下令有关部门，将新翻译的经论抄写九部，颁发给雍、洛、相、兖、荆、扬等九州，让人辗转流传。法师再次请求题写经名，皇帝才恩准。到这一年八月四日，序文撰写完毕，共七百八十字，题为《大唐三藏圣教序》，冠在新经之首。在明月殿，命弘文馆学士上官仪将所写的序对群臣宣读，文采灿烂如锦霞舒展，光赞至极，所有百官都欢喜庆贺。当时还是太子的高宗皇帝，又撰写了《述三藏圣教序记》，共五百七十字。"

translations[28]["modern"] = "【朝野归敬】【义解】两位圣人的序文出来之后，法师又上表谢恩，承蒙敕书回复说：“朕才德比不上珪璋美玉，言辞惭愧不能博达，对于内典尤其不熟悉，昨天写的序文，十分鄙拙，只怕玷污了金简，在珠林里标上瓦砾。忽然收到来信，承蒙谬赞，反省自身，更加厚颜，善名不足以相称，空劳致谢。”法师又上表再次谢恩，敕书回复说：“朕平时不读佛经，也没有才智，忽然写了论序，反而玷污了经文，看完来信，承蒙枉加褒奖，惭愧得到虚美，只增添了真正的惭愧。”从此以后，四方道俗手舞足蹈，歌咏赞美的声音连绵不断，内外传扬，不到一天就传遍天下。慈云再次荫蔽众生，慧日重放光明，归依的人如同波浪回旋、云雾委积，所谓在上位的人教化下面的人，就像风吹草伏一样。皇帝因此赐给法师摩云纳袈裟一领，精妙冠绝古今，价值万金，又下令天下寺观各度五人出家。冬十月，法师随皇帝驾还京城，安置在北阙的弘法院。"

translations[29]["modern"] = "【慈恩译场】【义解】皇帝下令建造慈恩寺，在寺的西北角建造翻经院，敕令法师移到那里翻译，配给弟子五十人，弘福寺旧处仍然给弟子十人看守。到永徽二年，法师请求建造梵本经台，蒙敕令布施物资，得以建成。到五年六月，迎请法师进入宫内，法师在临文等殿翻译《发智论》等经论。过了几天，皇帝降下飞白书手诏说：“师父年事已高，这里地方狭小，身体还好吗？”又显庆年间的恩敕说：“大慈恩寺僧玄奘所翻译的经论既然是新译，翻译的文义必须精当，应当令太子太傅、尚书左仆射燕国公于志宁，中书令兼检校吏部尚书、南阳县开国男来济，礼部尚书、高阳县开国男许敬宗，黄门侍郎兼检校太子左庶子、邠阴县开国男薛元超，守中书侍郎兼检校太子右庶子、广平县开国男李义府，当时时查阅，有不通顺的地方，就随事润色，如果需要学士，酌情征召三两人。”"

translations[30]["modern"] = "【请住少林】【义解】又法师请求皇帝御制大慈恩寺碑文，蒙恩准许，碑文写成之后对法师多有褒赞，法师又上表请皇帝亲笔书写，又蒙恩准许。书写完毕，法师认为这是佛门再兴的荣耀，于是和京城僧人制造幢盖等迎接，皇帝又下令让在场的王公、太常九部乐以及长安、万年两县的音声，一千多辆车助送，皇帝在安福门观看，光扬佛法的盛况，难以一一详述。皇帝又赐给法师摩云纳袈裟一领，和先前赐的一样精妙，还有其他当时的服饰一百多件。显庆二年，皇帝驾幸洛阳宫，法师提前前往，安置在称翠宫，在大内丽日殿翻译《观所缘缘论》等，又翻译《大毗婆沙论》等论，在所到之处从不停止。少室山西北，缑氏旧县南的游仙乡控鹤里凤凰谷，是法师的出生地；少室山北的少林寺，是魏孝文帝所建立的，极有山泉之美，是菩提流支翻译佛经的地方，法师心里想要栖身隐居，到九月，上表请求住在少林寺。"

translations[31]["modern"] = "【帝敕留京】【义解】为国翻译佛经，承蒙皇帝亲笔回信说：“省览表章，知道法师想要隐居岩泉，追踪慧远、林公而超越古人，寄心禅寂，效法澄公、罗什而规范当世，朕十分钦慕您的风范。朕功业空疏、学识寡少，不能探究高深的道法，但以浅识薄见来看，这样做未见得合适。法师是三界的津梁，四生的汲引者，智慧明亮如同心灯，禅定凝寂如同意水，不是情尘所能遮蔽，岂是识浪所能惊动？道德所在之处就可以安住，何必一定要在太华重岭；空寂之理可以体悟，难道只有少室重峦？希望收回您的请求，不要再上奏了。市朝大隐，不只是古代贤人才可贵；见闻弘法利益众生，在当代更值得珍重。”既然有皇帝的遗命，法师不敢再次请求。显庆三年，皇帝敕令为皇太子在濮王旧宅建造西明寺，下令给法师上房一间，新剃度僧人十名作为弟子。《大般若经》在这个地方很受重视，前代虽然翻译过，但没有完备，诸位大德都请求依照大本重新翻译，而《大般若经》总共有二十万偈，可以译成六百卷。"

translations[32]["modern"] = "【玉华译经】【义解】法师认为在京城事务太多，恐怕难以最终完成，于是多次请求居住在山中，才蒙恩准许，前往玉华宫寺翻译，仍然敕令供给完全和在京城一样。到了玉华寺，在显庆五年正月一日开始翻译《大般若经》，到龙朔三年十月二十三日全部译完，总共四处十六会的说法，共六百卷。中间又翻译了《成唯识论》《辨中边论》《唯识二十论》《品类足论》等。到十一月二十三日，命窥基带着表章，请圣上制作《大般若经》序。到十二月七日，在蓬莱宫呈进，当时通事舍人冯义宣口宣敕令准许。法师从年少以来，常愿生在弥勒佛所在之处，等到游历西方，又听说无著菩萨兄弟也愿生睹史多天宫奉事弥勒，都如愿以偿，都有证验，更加勉励自己。自从到了玉华寺，每次翻译以及礼忏的时候，都发愿上生睹史多天见弥勒佛，除了翻经的时候，无论昼夜，心心相续。"

translations[33]["modern"] = "【预知时至】【义解】没有片刻荒废。从翻译完《大般若经》之后，就不再翻译，只是行道礼忏。到麟德元年正月一日，玉华寺僧众等请法师翻译《大宝积经》，法师推辞说：“我知道这部经和汉土众生没有缘分，纵然翻译也译不完，你们坚持请求的话也免不了。”法师说：“翻译一定不满五行。”于是翻译了四行就停下了，对弟子以及翻经僧等说：“有为法必然归于磨灭，泡沫幻化一般的身体，怎么能长久停留？现在麟德元年，我年纪六十三岁，一定会在玉华寺去世，如果对经论有疑问，应当赶快来问，不要留下后悔。”徒众听了，没有不惊讶哭泣的，都说：“和尚您身体康健，年纪也没到老耄，为什么忽然说这样的话？”法师回答说：“这件事我自己知道，不是你们所能了解的。”这时候法师还没有患病，徒众面面相觑，都心生疑惑。到正月三日，法师又告诉门人：“我恐怕无常到了，想要去辞别佛像。”于是和弟子等人前往先前建造的俱胝像前。"

translations[34]["modern"] = "【示疾辞众】【义解】礼忏辞别。那些翻经僧以及弟子中，辞别要回京城探亲的，法师都告诉他们说：“你们好自去吧，我所有的衣钵经书，你们都带走，我和你们告别，你们也不用再来了，就算再来也见不到我了。”要走的人回答说：“和尚身体康健，一定不会有这样的事。”法师回答说：“这不是你们能知道的。”走的人果然再也没能见到他。到正月八日，弟子僧玄觉夜里梦见一座高大的木浮图，高峻庄严，正要瞻仰，忽然倒塌崩裂，心中一惊就醒了。天亮之后来参礼，详细说了这件事，法师告诉他说：“这件事是关于我的，和你无关，不要忧虑害怕。”到正月九日申时，法师又告诉玉华寺寺主慧德等人说：“我必定要死了，经中说这个身体可恶，如同死狗。我舍命之后，不要停放在宫寺里，应当在山原安静的地方安置，做一个能容身的棺材，再做一个外棺，用粗席子抬送到那里，可以依照教法火葬，这是最好的。”慧德等人惊叹，没有想到马上就会发生这件事。"

translations[35]["modern"] = "【瑞相现前】【义解】到当天傍晚，法师向后房去，过一条小水沟时伤了脚，最初四天还能像平常一样行动，到十三日就卧病在床，到十六日，闭眼睁眼之间，频频看到有白莲花，比盘子还大，光净鲜洁。到十七日，又看见无数百千人身形高大，都穿着锦衣，带着锦绮、各种花宝，来庄严法师所住的房屋，依次逐渐庄严，遍满翻经院内外的堂殿，直到山林，都用宝饰、花幡、幢盖装饰，又奏起音乐。后来看见门外有无数宝车，载着百味饮食以及各种香果药物，都不是人间之物，都拿来献给法师。法师推辞说：“这样的供具是六通圣者所受用的，我还没有这样的功德，不敢承当。”虽然恳切辞让，但进献的人不停止，侍者惊动触碰了法师，法师睁开眼，对寺里的僧众详细说了刚才的事。寺主慧德当夜在十分明亮的月色下，看见告坎山上的树都变成白色的幢盖，又看见两个人抬着一乘宝舆。"

translations[36]["modern"] = "【录经留嘱】【义解】装着各种肴膳，布满山谷，好像有人来奉献，很快就来禀告详细陈述了这件事，法师说：“我一生以来所修的福慧，根据这些所见来看，功夫不会白费，确实所发的愿没有错谬。”于是命翻经僧嘉尚，抄录近来所翻译的《大般若经》《瑜伽论》等大小乘经论，总共翻译了七十五部，合计一千三百三十一卷，让他诵读，法师自己十分欣慰庆幸。又说：“我的无常期到了，应当告诉门徒都来告别。”到二十一日，寺主慧德梦见无量金像，说是千佛，在东方翻经院上空显现之后隐没。到二十二日，门徒都聚集了，法师让作舍堕法，将所有衣物以及非衣物的东西全部施舍，造十万俱胝佛像，又请僧人转读行道，烧灯供养，洗浴众僧。到二十三日，斋供完毕，正午让工匠在嘉寿殿用香涂香木树菩萨像的骨架，当着寺众以及门徒的面。"

translations[37]["modern"] = "【安详圆寂】【义解】一一和众人告别诀别，又写了遗表，由弟子窥基奉进。法师于是默然正念，后人说偈教旁边的人诵道：“南无弥勒如来应正等觉，愿与一切含识，迅速亲奉慈颜；南无弥勒如来所居内众，愿舍命之后，一定往生其中。”到二月四日，看病的僧人明藏看见两个人，各高一丈多，穿着白衣戴着白冠，各用一只手共同擎着一朵大白莲花，花台有三层，十分可爱，像小车轮那么大，到法师面前站着，说道：“无量劫来恼乱众生的各种定业因缘，因为这一点小病轻微受报，就都除灭了，应当欢喜，不要忧愁烦恼。”法师见了之后，合掌很久，自己转过身体，以右胁着床，双腿重叠，右手托着头，左手伸开放在大腿上，直到命终，再也没有转动。明藏又问：“见到什么瑞相？”法师回答说：“不要问，妨碍我正念。”到五日中夜，弟子光等人又问。"

translations[38]["modern"] = "【身后哀荣】【义解】“和尚一定能生在弥勒面前吗？”法师回答说：“决定能生。”说完就舍命圆寂。过了六十天，头发逐渐长出来，颜色和生前一样，红白没有变化，还有香气，没有其他异味。法师得病的时候，翻经使许玄备详细奏闻，蒙敕令派医生带药前去看望，等医生赶到，法师已经去世，医生没赶上。圆寂之后，坊州刺史窦师备上奏朝廷，恩敕令葬事所需都由官府供给。接着奉敕旨：“玉华寺僧玄奘既然已经圆寂，翻经的事情暂且停止，已经翻译完成的，依照旧例由官府抄写，其余未翻译的梵本，交付慈恩寺妥善保管，不要让损失。玄奘的弟子以及翻经僧，先前不是玉华寺僧人的，都各自放回本寺。”又奉敕旨：“已故僧人玄奘，葬日应当派京城僧尼制造幢盖，送到墓地。”冥祥先前记录的事迹十分繁杂，不能一一列述。法师蒙两位皇帝珍重敬重，布施的绵帛绫彩一万多匹，上等纳袈裟、当时的服饰等数百件，法师得到之后。"

translations[39]["modern"] = "【散财济众】【义解】都为国造塔，书写俱胝绢像一千帧、贤劫千佛像一千帧、弥勒佛像一千帧，佛像十万俱胝，洗浴众僧，布施穷人，一点积蓄都没有，随得随散，只以翻译传法为要务。每翻译一部经，都急切地担心译不完，一部译完了，就欢喜庆贺说：“用这个来报答四恩。”我听说八正道的旨义，实在是出离苦海的津梁；一乘的宗旨，诚然是登涅槃的阶梯。只是因为众生根机未熟，致使佛法蕴藏在葱岭以西；佛法演化的时机成熟，才流布到交河之地。到摩腾入汉，教法在伊洛一带阐扬；康僧会游吴，义理覆盖荆楚之地。从此以后，人人修行解脱之因，家家建立菩萨之业。由此可知传法的利益，是十分广博的。法师耸千寻坚劲的品质，澄万项波澜的学识，以救度沉溺世俗为心忧，以匡正大法为己任，所以能跋涉重阻求取佛经，历经危途寻访大道，被异域所珍重，获得全部真经。如来一代所说的教法。"

translations[40]["modern"] = "【西行功业】【义解】鹫峰方等的教法，鹿苑半字的经文，乃至后来的圣者马鸣、龙树、无著、天亲等人所造的论典，以及灰山住部等十八部异执的宗义，五部不同的旨趣，都收罗研究、通达其中的意旨，完全得到其中的文义。还有佛陀一生化迹的地方，如泥洹坚固之林、降魔菩提树、迦路崇高之塔、那竭留影之山，都亲身礼敬，没有遗漏。心愿满足，见闻周遍，将要带回本土，于是缮写大小乘法教六百五十七部，请得转法轮像等七躯、佛肉舍利一百多粒，在贞观十九年春正月二十五日回到长安，道俗奔走迎接，全城罢市。此外法师此行行程数万里，历经各种危难，如大寒冰冻的雪山、飞波激浪的险川、厉毒黑风的瘴气、猛兽成群的险境，都是法显失去同伴、智严遗落伙伴的地方，是班固、张衡没有到过，章亥、竖亥没有游历过的地方，法师孤身前往，安然无阻，在印度河流域之外传布唐风，在五印度之间宣扬国德。"

translations[41]["modern"] = "【译经功德】【义解】使得远方的王侯倾心向化，仰望朝廷，虽然是圣上的威德远感，也有法师宣扬传述的功劳。自从归国翻译宣扬经文，如同在庵园初次说法一样，精深的文义如同金口新开。法师珍惜每一寸光阴，精进不懈，神气充裕，没有阻滞。处理完事务之后，还给各位大德讲西方圣贤著作的文义，词旨的深浅、部类的不同，以及年少时在这里周游讲肆的事情，高论畅谈，十分动听，完全没有疲倦，他的精力过人到了这种地步。法师回国以来，到现在二十年，合计翻译梵本七十五部，译成唐言，总共一千三百四十一卷，还有五百八十二部没有翻译。现在所译的《大般若经》《瑜伽论》《大毗婆沙》《顺正理》等，都是镇国之宝，是学人的渊薮。然而译经的事情，从汉代摩腾开始，到三藏法师为止，前后道俗共有一百多人。前代翻译的人，多是婆罗门法师。"

translations[42]["modern"] = "【译事超古】【义解】因为刚到东土，方言不通，承受翻译的人领会困难，每传一句，都要反复斟酌迟疑，所以多有颠倒讹误。现在法师唐梵两种语言都明达，翻译起来便巧，如同拿一件东西放在掌上给人看，清清楚楚没有差别，所以时间没有多久，功效却超过前贤几倍。比如鸠摩罗什号称精通秦言，译经十多年，只译了二百多卷，用这个来比较，难易就显而易见了。可悲的是法师寿命短促，没能完成他的志向，呜呼哀哉！明德二年八月，感得此记，冥详撰（云云），大师付法传中引用的行状文，彼此符合，尤其值得珍重。法印权大僧都贤宝记。以上贤宝师感得的本子十分珍贵秘藏，今年是这位法师三百五十忌辰，为了追荐装饰，缮写完毕。延亨四（丁卯）岁六月二十五日僧上贤贺（时年六十四岁）朱书嘉保三年八月二十八日校点完毕。"

