t[1]["modern"] = "【龙王供佛】【义解】这时，诸位龙王和他们的眷属从座位上起身，偏袒右肩，右膝跪地，合掌向佛，用无量阿僧祇种殊胜微妙的香花、涂香、末香、烧香，以及各种花鬘、衣服、幢幡、缯彩，演奏音乐歌咏，献上宝花、宝帐，杂佩、流苏，悬挂各种璎珞、龙华珠网，广设供养器具，以坚定、尊重、恭敬、不可思议、最殊胜清净的淳厚信心供养如来。"

t[2]["modern"] = "【发愿供养】【义解】作完这样的供养之后，右绕佛陀三匝，退在一边站着，同时发出宏大誓愿：“愿将一切世界微尘数那么多的供具来供养：每一粒微尘都广大如海的我们的身海、诸佛菩萨道场的大众海、一切世界不可计数的大海、一切地水火风四大微尘等海、一切色光如微尘数、每一微尘中超过算数的无量阿僧祇不可数、不可思量、不可称说、超过言说的身海；每一身中又有无量手，不可计数如海云，化现出种种供养器具，遍布十方，每一微尘中不断不散也如海云；又愿一切诸佛菩萨海，我们永远在在处处作种种供养，所有无量阿僧祇不可思量、不可称说、不断不散的供养，一切十方都如同普贤菩萨行身海云，普遍覆盖十方虚空，以心愿力的缘故，成就菩萨之身也如海云。那时一切宝色光焰不断不散的一切日月身轮海云、一切宝帐流苏众花海云、一切宝帐大光明藏楼阁海云、一切树枝箧藏海云、一切香色示现海云、一切言语妙声种种音乐海云、一切香树海云，都充满虚空，以威神力建立这样无量阿僧祇不可思量、不可称说、不散不断的海云，供养一切诸佛菩萨海，尽未来际恭敬、尊重、礼拜、供养，这样供养。"

t[3]["modern"] = "【宝云供佛】【义解】一切大庄严境界摩尼王藏如同电光的海云，充满虚空，以威神力建立；又愿对一切诸佛菩萨海，尽未来际恭敬、尊重、礼拜、供养，这样供养。一切普照宝雨庄严摩尼王海云、一切宝焰照明佛化音响常不休息摩尼王海云、普乐一切佛法音响摩尼王海云、普十方示现宝焰诸佛化光海云、一切庄严不坏不散都影现其中的摩尼王焰灯海云、一切诸佛境界随顺摩尼王海云、不可思议诸佛国土、如来所在处都影现其中的摩尼王海云，像这样的供养我们都奉献。一切种种宝尘中的三世佛身及影现的毘卢遮那摩尼王海云，充满虚空，以威神力建立示现之后，对一切佛菩萨海云如同大海一样，尽未来际我们恭敬、尊重、礼拜、供养，这样供养不散不断。"

t[4]["modern"] = "【楼阁供养】【义解】又愿以一切宝香众花楼阁海云、无量色宝一切摩尼王庄严楼阁海云、宝灯香焰楼阁海云、一切真珠种种楼阁海云、一切花鬘海云、无量众宝庄严璎佩流苏楼阁海云，充满虚空，这样建立之后，十方无量普焰火藏一切庄严和合化成楼阁海云、一切宝笛宝轮示现无量庄严十方楼阁海云、一切庄严雕饰普遍楼阁海云，普十方门的飞楼、栏楯、铃网、帐帷海云，充满虚空，以威神力建立都示现出来，对一切佛及菩萨海，尽未来际恭敬、尊重、礼拜、供养，这样供养。"

t[5]["modern"] = "【师子座供】【义解】又愿以吐金宝杂缕璎珞宝欢喜藏师子座海云、花光杂藏师子座海云、因陀尼罗阎浮那池莲华杂藏师子座海云、摩尼灯莲华藏师子座海云、焰幢摩尼莲华杂藏师子座海云、宝饰莲华杂藏师子座海云、因陀罗青色妙丽光焰莲华藏师子座海云、无尽光焰照耀威势莲华藏师子座海云、一切莲华藏出诸宝焰师子座海云、佛莲华藏生诸妙声宝焰师子座海云，不断不散充满虚空，以威神力建立之后，尽未来际恭敬、尊重、礼拜、供养，这样供养。又愿以一切宝香杂树海云、普十方门所有树叶都如合掌、香气芬馥的海云、一切树色无边际庄严示现海云、一切树间花云垂布海云、诸树庄严出无边箧海云。"

t[6]["modern"] = "【宝树供养】【义解】一切宝树焰鬘照耀海云、所有一切旃檀树枝都示现半身菩萨海云、一切菩萨胜轮光树不可思议庄严放光、一切无边宝衣箧笥如日电照耀海云、一切诸树普出妙响、闻者爱乐海云、无边色宝妙莲华藏师子座海云、普十方面摩尼宝王电光曜藏师子座海云、诸璎珞藏庄严雕刻师子座海云、种种宝焰灯鬘之藏师子座海云、普声音藏能出宝雨师子座海云、一切香华璎珞宝藏师子座海云、一切佛座庄严示现摩尼王藏师子座海云、一切庄严流苏帷帐栏楯妙藏师子座海云、一切诸树摩尼枝条宝箧笥藏师子座海云、杂香铃网垂帷周布日电曜藏师子座海云，不断不散充满虚空，作完这些事之后，对一切佛及菩萨海，恭敬、尊重、礼拜、供养，这样供养。"

t[7]["modern"] = "【宝帐供养】【义解】又愿以诸如意王摩尼宝帐海云、因陀罗青庄严校饰宝花鬘帐海云、一切众香摩尼宝帐海云、宝焰色身灯光明帐海云、诸佛神通放光出响摩尼王帐海云、杂种摩尼诸宝衣服一切庄严现放光帐海云、一切众花放光宝帐海云、种种铃声普震网帐海云、无边际色莲华罗网杂摩尼台莲华网帐海云、金色鬘焰火幢帐海云、不可思议庄严光影诸璎珞帐海云，充满虚空不断不散，这样建立之后，对一切佛及菩萨薄伽梵海云，恭敬、尊重、礼拜、供养，这样供养。"

t[8]["modern"] = "【宝盖供养】【义解】又愿以一切摩尼宝盖海云，这样建立等充满虚空的十方焰火庄严华盖海云、无边际色真珠箧盖海云、一切诸佛菩萨大悲门响摩尼王盖海云、种种杂宝光焰鬘盖海云、普宝丽香庄严铃网垂带帐盖海云、一切摩尼宝树垂条帐盖海云、日焰照耀摩尼王宝烧香散香一切香盖海云、栴檀末香犹如箧藏普震遍盖海云、诸佛境界普广庄严照耀震盖海云，不断不散对一切佛诸菩萨海，恭敬、尊重、礼拜、供养，这样供养。"

t[9]["modern"] = "【光轮供养】【义解】又愿以一切众宝光轮海云、众宝焰身照耀不绝光轮海云、华云照耀光轮海云、一切宝焰佛化光轮海云、一切佛刹影现光轮海云、普佛境界能出雷音宝枝光轮海云、一切毘琉璃宝性摩尼王焰光轮海云、无边众生色心刹那示现光轮海云、音声悦可诸佛光轮海云、一切众会道场音声教化众生摩尼宝王光轮海云，对一切佛诸菩萨海恭敬、尊重、礼拜、供养，这样供养。"

t[10]["modern"] = "【光焰供养】【义解】又愿以一切摩尼箧焰海云、一切诸佛色声香味触光焰海云、一切宝焰海云、一切佛法出声震焰海云、一切佛刹庄严照耀光焰海云、一切楼阁华焰海云、一切宝笛光焰海云、一切诸劫展转诸佛出世教化众生法音震焰海云、无尽众生妙宝示现一切华鬘光焰海云、一切诸座庄严示现光焰海云，不断不散对一切佛诸菩萨海恭敬、尊重、礼拜、供养，这样供养。又愿以不断不散无边色宝光焰海云、普光摩尼王海云、一切佛刹普广庄严照耀光焰海云、一切香焰海云、一切庄严光焰海云、一切化佛身焰海云、诸杂宝树花鬘光焰海云、一切衣服光焰海云、菩萨无边诸行名称摩尼王焰海云、一切真珠灯焰海云，不断不散对一切佛菩萨海云，犹如大海，恭敬、尊重、礼拜、供养，这样供养。"

t[11]["modern"] = "【发愿毕坐】【义解】又愿以不可思议一切香华种种海云、一切宝焰莲华罗网海云、无边际色摩尼王宝光轮海云、一切宝色真珠箧笥海云、一切宝香栴檀末香海云、一切宝盖海云、悦可众意清净妙音摩尼宝王海云、日焰摩尼光轮璎珞流苏海云、无边宝箧海云、一切普贤色身海云，不断不散对一切佛菩萨海云，犹如大海，恭敬、尊重、礼拜、供养，这样供养。”这时八十四亿那由他百千诸龙发完这个大愿之后，右绕佛陀三匝，头面顶礼，退在一面站立。佛陀说：“你们坐下吧。”这时诸位龙王各自坐下，大众中有一位大龙王，名叫阿难多波利迦罗娑伽罗迷伽诃毘踰呵低树曼荼罗叱多囉伽罗王，是三千大千世界诸龙的君主，住于不退转地，以大愿力来到阎浮提，为了供养如来世尊，至心礼拜、听闻正法的缘故。"

t[12]["modern"] = "【龙王请法】【义解】这时阿难多波利迦娑伽罗龙王从座位起身，偏袒右肩，右膝跪地，合掌向佛一心敬礼，对佛说：“世尊！我现在想请问如来世尊应正遍知一件小事，如果您允许，我才敢发问。”这时世尊听了这话，告诉阿难多波利迦娑伽罗龙王说：“大王！随你发问吧。若有想问的，现在正是时候，我会为你分别解说，满足你的心愿。”当时龙王就对佛说：“世尊！怎样才能让一切龙族脱离苦恼，得到一切安乐，满足我的心愿之后，这阎浮提按时降雨，百谷、果实、药材、花卉、树木、丛林、土地所生的作物都增长滋味，滋味增长之后阎浮提的人民就能得到安乐？”问完之后，佛告娑伽罗大龙王说：“善哉善哉！龙王！你现在怜悯一切众生，问这样的事。仔细听，仔细听，好好忆念思考，我现在就为你解说。"

t[13]["modern"] = "【慈心持咒】【义解】善男子！我有一个法门，如果一切龙能受持，就能灭尽所有痛苦，身心安乐。是哪一法呢？就是慈心。若是天若是人能修习慈心，火不能烧、刀不能伤、水不能漂、毒药不能害，内外盗贼都不能侵犯，睡觉醒着都安稳，能谨慎保护自身，有大福德威德，生生世世身相端正，见到的人都喜爱，所去的地方没有障碍，一切天人都不能恼乱，远离各种苦恼，心常欢喜，享受各种快乐，得到上人之法，临命终时能生到梵世。大龙王！这样的慈心能利益天人，身、口、意三业的慈心应当经常修习。”“再者大龙王！有陀罗尼句，名叫施安乐，诸位龙族应当经常诵持，能除去一切龙族的苦恼，能让一切得到安稳快乐。得到快乐之后，那些龙族在阎浮提依照时节降雨，百谷、果实、药材、花卉、树木、丛林都能顺利生长。”龙王对佛说：“什么叫做施一切乐陀罗尼句呢？"

t[14]["modern"] = "【施安乐咒】【义解】”这时世尊就说咒曰：【陀罗尼照录】怛地也他（其咒文中字口傍作者皆转舌读之，注引字者皆须引声读之）陀呵（引）囉尼陀呵（引）囉尼（一）　欝多（引）囉尼（二）　三波囉帝（丁利反）师尿（󰠀利反）（三）　毘闍耶跋唎拏萨帝夜波羅帝闍若长那跋坻（四）　欝多波（引）达儞（五）　比那（引）汉儞（六）　阿比屣（引）遮儞（七）　阿陛毘耶（引）呵（引）罗（八）　首婆呵（引）跋帝（九）　阿祁（引）末多（十）　野咥（香利反）（十一）　宫婆（引）罗（引）（十二）　擗咥（香利反）婆（引）呵（引）（十三）　摩（引）囉吉犁（引）舍（引）达那波（脯藍反）（十四）　輸陀耶摩（引）钳尼唎（引）呵迦达摩多（十五）　輸陀呵（引）盧迦（十六）　毘帝寐囉何囉闍婆豆佉舍摩那（十七）　薩婆佛陀呵（引）婆盧（引）迦那（引）地师恥坻（引）（十八）　波羅闍若（引）闍若（引）那擗醯（引）莎呵【义解】佛说：“大龙王！"

t[15]["modern"] = "【称念佛名】【义解】这个陀罗尼，名叫施一切诸龙安乐，诸位龙族应当经常诵持，一切生活所需常得自在，进入自在之门，被诸如来威神护持，给一切龙身心安乐。再者大龙王！有一位佛世尊，名号是云生建大庄严威势之藏华光智幢持水锋轮金德净光毘卢遮那髮際生性如来应供正遍知。大龙王！应当受持、读诵、忆念、称名、礼拜，听到这位佛的名号，能除去龙种的一切苦恼，一切龙宫、一切龙姓、一切和合的一切龙生处、一切龙王、一切龙女、一切龙眷属，所有苦恼都能给予安乐。"

t[16]["modern"] = "【云雨诸佛】【义解】还有无量诸佛名号，分别是：【贤劫云雨诸佛】南无婆伽婆帝毘盧遮那藏大雲如來、南無婆伽婆帝雲生雲照曜如來、南無婆伽婆帝雲持水如來、南無婆伽婆帝雲威德如來、南無婆伽婆帝生大雲如來、南無婆伽婆帝奮迅輪能壞雲如來、南無婆伽婆帝電焰聚如來、南無婆伽婆帝大雲羯摩勇健如來、南無婆伽婆帝須彌善雲如來、南無婆伽婆帝摩訶伽那雲如來、南無婆伽婆帝大雲輪如來、南無婆伽婆帝雲光如來、南無婆伽婆帝大雲師子座如來、南無婆伽婆帝大雲蓋如來、南無婆伽婆帝善示現大雲如來、南無婆伽婆帝雲覆如來、南無婆伽婆帝雲生光輪覆十方頻申雷震大妙鼓音如來、南無婆伽婆帝大雲清涼歡喜奮迅雷如來、南無婆伽婆帝廣雲如來、南無婆伽婆帝虛空雲如來、南無婆伽婆帝毘羯磨勇雲如來、南無婆伽婆帝雲出妙聲如來、南無婆伽婆帝雲示現如來、南無婆伽婆帝廣出雲如來、南無婆伽婆帝雲羅羅如來、南無婆伽婆帝雲奮震如來、南無婆伽婆帝雲央伽那如來、南無婆伽婆帝雲如衣覆如來、南無婆伽婆帝雲婆盧訶迦夜如來、南無婆伽婆帝雲衣如來、南無婆伽婆帝彌伽婆羅呵迦耶如來、南無婆伽婆帝出雲如來、南無婆伽婆帝散雲如來、南無婆伽婆帝雲欝鉢羅花如來、南無婆伽婆帝火雲香如來、南無婆伽婆帝大上雲如來、南無婆伽婆帝大雲自在如來、南無婆伽婆帝大雲作光如來、南無婆伽婆帝大雲德如來、南無婆伽婆帝大雲作摩尼寶雲如來、南無婆伽婆帝雲碎壞如來、南無婆伽婆帝雲莖幹如來、南無婆伽婆帝灌水雲葉如來、南無婆伽婆帝壞虛空雹如來、南無婆伽婆帝大雲勝聲如來、南無婆伽婆帝大雲出聲如來、南無婆伽婆帝大雲出雨如來、南無婆伽婆帝欝妻俱殊婆三訶羅拏雲如來、南無婆伽婆帝大六字水雲如來、南無婆伽婆帝大雲饒水如來、南無婆伽婆帝海滿雲如來、南無婆伽婆帝潤澤遍身雲如來、南無婆伽婆帝無邊雲色如來、南無婆伽婆帝毘耶一切差別大雲閻浮德威月光焰雲如來等應正遍知三藐三佛陀。【义解】大龙王！"

t[17]["modern"] = "【持名降雨】【义解】这些佛的名号，一切龙族如果能诵持、称名、礼拜，就能除去一切痛苦，得到欢喜快乐，在阎浮提随时降雨，百谷、果实、药材、花卉、树木、丛林都能顺利生长。”这时三千大千世界主大龙王对佛说：“我现在要请诸佛所说的陀罗尼章句，在未来世末世的阎浮提中不降雨的地方，如果诵这个咒就能降下甘雨；如果恶世凶险艰难、非法兴起的时候，疫病流行、星宿失度，如果想要灭除以上这些恶事，以佛力的缘故、大悲心的缘故、怜悯一切众生的缘故，受持这样的陀罗尼句，说这个咒的时候一切诸龙都生欢喜，一切诸天都踊跃，破坏魔的境界，一切众生的四百四病都令不生，诸根安稳，一切恶事都能除灭。”这时世尊听了三千大千世界龙王这样的话，赞叹说：“善哉善哉！大龙王！你也像诸佛一样饶益众生，怜悯众生给予快乐，请求这件事真是太好了。"

t[18]["modern"] = "【勇猛幢咒】【义解】仔细听，仔细听，好好忆念思考。大龙王！我现在要说从前在大悲雲生如来那里听闻的频申勇猛幢陀罗尼，过去诸佛已经宣说，以威神加护，我现在也随顺宣说，为了利益一切众生，怜悯众生给予快乐，在未来世如果大旱的时候能降雨，如果水涝的时候也能令雨止息，疫死险难都能灭除，能召集诸龙，能令龙天欢喜踊跃，能破坏一切魔的境界，能令众生具足安乐。”于是说咒曰：【陀罗尼照录】怛姪他摩訶若（引）那（引）婆婆呵（引）薩尼（一）　失梨帝殊羅欹彌（二）　地履荼毘伽囉尛鉢耶囉僧呵怛禰（三）　波羅摩避囉闍（四）　尼摩羅求那鷄鬪蘇栗耶波羅毘（五）　毘摩嵐伽耶師𰈂（六）　婆呵囉婆呵囉（七）　三婆呵囉三婆呵囉（八）　豆豆毘（九）　呵那呵那（十）　摩呵鉢利鞞（十一）　比豆那摸呵陀迦嵐（十二）　鉢囉若伽囉輸提（十三）　鉢利富利那彌帝利彌帝利地囉摩那娑斤提（十四）　彌多嵐步陀利（十五）　闍羅闍羅（十六）　闍羅闍羅（十七）　闍嵐步大離（十八）　菩澄伽俱蘇彌（十九）　達舍跋隷（二十）　遮妬裴舍阿囉提（二十一）　阿吒達舍毘尼吒佛陀達彌（二十二）　輸頗魔帝分若曷囉翅（二十三）　叔迦羅達摩三摩禰坻（二十四）　鉗毘囉毘囉闍息雞（二十五）　毘富隷毘舍師沙波羅鉢帝（二十六）　禰囉蘇羅波達彌（二十七）薩婆盧迦誓薩吒（二十八）　失離薩吒波羅（二十九）　鉢羅婆梨（三十）　阿奴怛利（三十一）　阿僧祇（三十二）　陀羅陀羅（三十三）　地利地利（三十四）　豆留豆留（三十五）　羶哆末坻（三十六）羶哆波卑（三十七）　遮羅遮羅旨利旨利（三十八）　朱留朱留（三十九）　波羅摩佛陀㝹末坻（四十）　摩呵鉢羅若波羅蜜坻（四十一）　莎呵南無若那（一）　婆伽羅毘盧遮那耶（二）　多他竭多耶（三）　南無薩婆佛陀（四）　菩提薩坻毘呵（五）【义解】“这时一切诸龙为了阎浮提降下甘雨的缘故受持此咒，后世末世恶灾流行时能令恶灾不起，诸佛菩萨发真实语重说咒曰：【陀罗尼照录】三耶挮淡（一）　娑羅娑羅（二）　斯利斯利（三）　蘇留蘇留（四）　那伽男（五）　闍婆闍婆（六）　時毘時毘（七）　殊復殊復（八）　摩呵那伽男（九）　阿伽車咃（十）　佛陀薩禰呵（十一）　闍浮提坻（十二）　婆羅婆利沙曇（十三）　遮羅遮羅（十四）　旨利旨利（十五）　周留周留（十六）　摩呵那伽地般帝男（十七）　阿伽車多蒲盧（十八）　摩呵那伽佛陀薩坻禰呵（十九）　閻浮提卑（二十）　波羅婆沙曇（二十一）　波羅波羅（二十二）　毘利毘利（二十三）　浮留浮留（二十四）　佛陀薩坻那（二十五）　薩婆那伽那婆呵耶沙禰（二十六）　迷帝囉質坻那（二十七）　迦樓那質坻那（二十八）　迦樓那質坻那（二十九）　牟地多質坻那（三十）　憂卑叉質坻那（三十一）　薩婆佛陀（三十二）　菩提薩埵地師咃禰那薩坻那（三十三）　摩呵耶那舍移那（三十四）　阿伽車他（三十五）　摩呵那伽提波怛耶（三十六）　蘇摩羅他佛陀那（三十七）　佛陀達摩那（三十八）菩提薩埵求那男（三十九）　波羅波羅（四十）　毘利毘利（四十一）　浮休留浮休留（四十二）　摩呵折嵐浮（四十三）　彌伽婆利陀利那（四十四）　摩呵浮闍迦波利迦羅（四十五）　彌帝利質帝那（四十六）　阿伽車他（四十七）　三摩羅多婆羅舍三男舍薩妬（四十八）　伽茶伽茶（四十九）　祇治祇治（五十）　渠籌渠籌（五十一）　憂伽囉俱嚧陀（五十二）　摩呵毘伽嚧囉嗜呵婆（五十三）　摩呵毘沙（五十四）　阿伽吒他迷帝羅質多（五十五）　婆利沙馱簸伊呵閻浮提卑（五十六）　薩婆多他竭多薩坻那（五十七）　蘇和呵【义解】“如果诵这个咒，阎浮提内一切诸龙都会来聚集，生起悲喜舍心，又以慈心降下甘雨。"

